entries[364754] = { ["name"] = "Raserei der Monstrosität", ["text"] = "Die Dauer von 'Monströse Gliedmaße' ist um 4 Sek. erhöht und die Fähigkeit gewährt [ Blut : 'Knochenschild' / Frost : 'Raureif' / Unheilig : 'Runenverderbnis' ] mit 2 Sek. schnellerer Frequenz. Zusätzlich erleiden Gegner, nachdem sie das erste Mal Schaden durch 'Monströse Gliedmaße' erlitten haben, 12 Sek. lang 20% mehr Schaden durch Euch." }
entries[364755] = { ["name"] = "Rasende Übertragung", ["text"] = "Die durch 'Recht des Todes' erhaltene Stärke ist um 3% erhöht und hält 2 Sek. länger an. Während Ihr Euch im Effektbereich von 'Recht des Todes' aufhaltet, ist Eure Runenmachterzeugung um 20% erhöht." }
entries[364756] = { ["name"] = "Bauplanreintegration: Schreckensmeduse", ["text"] = "Sofort\nGewährt der Protoformschmiede den Bauplan für die Schreckensmeduse und ermöglicht es Euch, sie mittels Protoformsynthese herzustellen." }
