entries[364811] = { ["name"] = "Essenzbarriere", ["text"] = "Wirken in 1.5 sek. 2 sek. Abklingzeit\nSurrounds the caster with a shield that lasts 20 Sek. and can absorb up to 25 Physical damage." }
entries[364813] = { ["name"] = "Mi Obet", ["text"] = "Wirken in 0.5 sek." }
entries[364814] = { ["name"] = "Einigkeit", ["text"] = "Runenschnitzmacht\nGewährt einen legendären Effekt Eures auserwählten Pakts.\nRunenschnitzen: Kopf, Hals, Schulter, Brust, Taille, Beine, Füße, Handgelenk, Hände, Finger, Rücken\nQuelle: Ihr benötigt einen respektvollen Ruf bei den Erleuchteten und müsst Runenschnitzen freigeschaltet haben, um diese Erinnerung kaufen zu können.\nBenötigt: Druide" }
entries[364815] = { ["name"] = "Seelenaffinität", ["text"] = "Ihr und die Euch verwandte Seele erhaltet jeweils einen Bonus auf einen Sekundärwert, der von ihrem Pakt abhängt. Für Eure verwandte Seele wird dieser Bonus halbiert, jedoch werden beide Boni verdoppelt, während Eure Verbindung ermächtigt ist.\n\nKyrianer : Meisterschaft um 571 erhöht.\nNachtfae : Tempo um 6% erhöht.\nVenthyr : Kritische Trefferchance um 6% erhöht.\nNekrolords : Vielseitigkeit um 6% erhöht." }
entries[364816] = { ["name"] = "Sündhaftes Schwelgen", ["text"] = "Jedes Mal, wenn 'Unersättliche Raserei' angewendet wird, wird die Dauer um 0,1 Sek. erhöht. Zusätzlich verbleibt 'Unersättliche Raserei' und überwältigt Euch nach Ende des Effekts 3 Sek. lang nicht." }
entries[364817] = { ["name"] = "Mi Obet" }
entries[364818] = { ["name"] = "Ungezügelter Schwarm", ["text"] = "Jedes Mal, wenn 'Adaptiver Schwarm' überspringt, besteht eine Chance von 60%, dass er sich in zwei Schwärme aufteilt." }
entries[364819] = { ["name"] = "Himmlische Geister", ["text"] = "Verringert die Abklingzeit von 'Konvokation der Geister' um 50% und die Dauer um 25%. 'Konvokation der Geister' hat eine erhöhte Chance, einen außergewöhnlichen Zauber oder eine außergewöhnliche Fähigkeit einzusetzen." }
entries[364821] = { ["name"] = "Kosmische Macht" }
entries[364822] = { ["name"] = "Kosmischer Schutz", ["text"] = "Kanalisiert (Wirken in 15 sek.)" }
entries[364824] = { ["name"] = "Einigkeit", ["text"] = "Runenschnitzmacht\nGewährt einen legendären Effekt Eures auserwählten Pakts.\nRunenschnitzen: Kopf, Hals, Schulter, Brust, Taille, Beine, Füße, Handgelenk, Hände, Finger, Rücken\nQuelle: Ihr benötigt einen respektvollen Ruf bei den Erleuchteten und müsst Runenschnitzen freigeschaltet haben, um diese Erinnerung kaufen zu können.\nBenötigt: Dämonenjäger" }
entries[364825] = { ["name"] = "Loderndes Gemetzel", ["text"] = "'Die Jagd' hüllt Euch in 'Feuerbrandaura', wenn Ihr Euer Ziel erreicht, und Eure Beweglichkeit wird pro getroffenem Gegner 12 Sek. lang um 4% erhöht." }
entries[364826] = { ["name"] = "Dämonischer Schwur", ["text"] = "Wenn der Dämon von 'Futter für die Flamme' explodiert, belegt er 5 Gegner in der Nähe für 5 Sek. mit 'Flammendes Brandmal'. Zusätzlich ist die Dauer von 'Zerschmetterte Seele' um 8 Sek. erhöht." }
entries[364827] = { ["name"] = "Blick der Agonie", ["text"] = "'Sündhaftes Brandzeichen' verursacht 10% mehr Schaden und Schaden durch [ Verwüstung : 'Augenstrahl' /\n\nRachsucht\n'Dämonische Verwüstung' ] erhöht die Dauer von 'Sündhaftes Brandzeichen' um 0.75 Sek." }
entries[364828] = { ["name"] = "Blinder Glaube", ["text"] = "'Elysischer Erlass' spaltet zusätzlich 2 geringe Seelenfragmente ab und gewährt Euch für 20 Sek. 'Blinder Glaube'. Jedes geringe Seelenfragment, das Ihr aufzehrt, während 'Blinder Glaube' aktiv ist, gewährt Euch 10 Jähzorn und 1% Vielseitigkeit, bis zu maximal 20%." }
entries[364829] = { ["name"] = "Verbannt", ["text"] = "40 Meter Reichweite\nSofort\nCauses an enemy to take 6% increased Physical damage for 20 Sek.." }
entries[364830] = { ["name"] = "Schläge der Verbannung", ["text"] = "Sofort\nGewährt den Angriffen des Zaubernden eine Chance, den erlittenen Schaden des Ziels zu erhöhen.\n(5s Abklingzeit)" }
entries[364831] = { ["name"] = "Interessiert", ["text"] = "15 Meter Reichweite\nSofort\nKonzentriert sich auf eine Kuriosität in der Nähe." }
entries[364832] = { ["name"] = "Verschlingen", ["text"] = "40 Meter Reichweite\nSofort\nInflicts Shadow damage to all enemies within 25 yards." }
entries[364833] = { ["name"] = "Verschlingen", ["text"] = "Wirken in 1 sek.\nFügt Gegnern in der Nähe alle 1.5 Sek. Schattenschaden zu." }
entries[364839] = { ["name"] = "Sündhafte Projektion", ["text"] = "Unbegrenzte Reichweite\nSofort\nSündhafte Projektionen verteilen sich nach 4 Sek. in verschiedene Richtungen, fügen anderen Spielercharakteren 20885 Schattenschaden zu und betäuben sie für 2 Sek.\n\nSündhafte Projektionen belegen von dem Effekt getroffene Spielercharaktere mit einem Stapel ' Bürde der Sünde '." }
entries[364840] = { ["name"] = "Sündhafte Projektion" }
entries[364843] = { ["name"] = "Gebrochener Kern", ["text"] = "Sofort\nDer bisher verursachte Schaden hat den Kern des aufmerksamen Wächters beschädigt. Alle Spielercharaktere erleiden alle 3 Sek. 12531 kosmischen Schaden." }
entries[364845] = { ["name"] = "Gebrochener Kern", ["text"] = "Unbegrenzte Reichweite\nSofort\nDer bisher verursachte Schaden hat den Kern des aufmerksamen Wächters beschädigt. Alle Spielercharaktere erleiden alle 3 Sek. 12531 kosmischen Schaden." }
entries[364846] = { ["name"] = "Abwerfen" }
entries[364848] = { ["name"] = "Abgeschlossen" }
entries[364850] = { ["name"] = "Sündhafte Projektionen", ["text"] = "300 Meter Reichweite\nSofort\nXanesh schindet die Seelen mehrerer Spielercharaktere, die nach 10 Sek. explodieren und den betroffenen Spielercharakteren 62539 Schattenschaden zufügen.\n\nDer Schaden nimmt ab, je weiter ein Spielercharakter von der geschundenen Seele entfernt ist." }
entries[364851] = { ["name"] = "Die Dämmerung wird kommen", ["text"] = "Sofort\nFür jedes von 'Licht der Morgendämmerung' getroffene Ziel besteht eine Chance von 50%, die verbleibende Abklingzeit von 'Zornige Vergeltung' um 2 Sek. zu verringern." }
entries[364852] = { ["name"] = "Einigkeit", ["text"] = "Runenschnitzmacht\nGewährt einen legendären Effekt Eures auserwählten Pakts.\nRunenschnitzen: Kopf, Hals, Schulter, Brust, Taille, Beine, Füße, Handgelenk, Hände, Finger, Rücken\nQuelle: Ihr benötigt einen respektvollen Ruf bei den Erleuchteten und müsst Runenschnitzen freigeschaltet haben, um diese Erinnerung kaufen zu können.\nBenötigt: Magier" }
entries[364853] = { ["name"] = "Harmonisches Echo", ["text"] = "Schaden, der mit der Verwundbarkeit von 'Strahlender Funke' belegten Gegnern zugefügt wird, hallt nach und fügt Eurem aktuellen gegnerischen Ziel sowie 4 Gegnern in der Nähe 25% des ursprünglichen Schadens zu." }
entries[364854] = { ["name"] = "Sündhafte Freuden", ["text"] = "Wenn Ihr [ Arkan : 'Freizaubern' ] [ Feuer : eine Aufladung von 'Feuerschlag' /\n\nFrost\n'Hirnfrost' ] verbraucht, wird die Abklingzeit von 'Spiegel der Qual' um 4 Sek. verringert. Wenn 'Spiegel der Qual' gebannt wird, wird die Abklingzeit um 45 Sek. verringert." }
entries[364855] = { ["name"] = "Tiefen des Todes", ["text"] = "Eure Zauber 'Feuerball', 'Frostblitz' und 'Arkanschlag' haben eine Chance, Euch für 8 Sek. 'Todesgeboren' zu gewähren. In der Gestalt eines Skelettmagiers wird der gewährte Zauberschaden für jeden von 'Feuerball', 'Frostblitz' und 'Arkanschlag' getroffenen Gegner um 1% erhöht." }
entries[364856] = { ["name"] = "Herz der Fae", ["text"] = "'Machtverschiebung' kann aus der Bewegung kanalisiert werden. Ihr erhaltet für jeden von 'Machtverschiebung' getroffenen Gegner 1% kritischen Trefferwert und Tempo, bis zu 10%. Hält 15 Sek. lang an." }
entries[364857] = { ["name"] = "Einigkeit", ["text"] = "Runenschnitzmacht\nGewährt einen legendären Effekt Eures auserwählten Pakts.\nRunenschnitzen: Kopf, Hals, Schulter, Brust, Taille, Beine, Füße, Handgelenk, Hände, Finger, Rücken\nQuelle: Ihr benötigt einen respektvollen Ruf bei den Erleuchteten und müsst Runenschnitzen freigeschaltet haben, um diese Erinnerung kaufen zu können.\nBenötigt: Mönch" }
entries[364858] = { ["name"] = "Ruf zu den Waffen", ["text"] = "'Waffen der Ordnung' ruft für 12 Sek. [ Braumeister : Niuzao, den Schwarzen Ochsen ] [ Nebelwirker : Chi-Ji, den Roten Kranich ] [ Windläufer : Xuen, den Weißen Tiger / Yu'lon, die Jadeschlange, ] zur Unterstützung an Eure Seite." }
entries[364859] = { ["name"] = "Finstere Lehren", ["text"] = "'Gefallener Orden' beschwört für 24 Sek. 1 zusätzlichen [Ochsen][Kranich][Tiger]adepten. Während Euer mystisches Portal geöffnet ist, verringern kritische Treffer mit Euren Fähigkeiten die Abklingzeit von 'Gefallener Orden' um [ Nebelwirker : 2.5 /\n\nBraumeister, Windläufer\n5 ] Sek." }
entries[364860] = { ["name"] = "Großzügiges Gebräu", ["text"] = "Eure Fähigkeiten haben eine geringe Chance, 'Knochenstaubgebräu' an der Position Eures Ziels einzusetzen." }
entries[364861] = { ["name"] = "Faelinienharmonie", ["text"] = "Eure Fähigkeiten schließen die Abklingzeit von 'Faelinienstampfen' 100% häufiger ab. Durch 'Faelinienstampfen' getroffene Gegner und Verbündete werden mit 'Faekontakt' belegt, was Euren Schaden oder Eure Heilung bei ihnen 10 Sek. lang um 8% erhöht." }
entries[364863] = { ["name"] = "Geblendet", ["text"] = "Sofort\nBemüht, das aktuelle Geschehen zu begreifen." }
