entries[364879] = { ["name"] = "Gabe der Creatii", ["text"] = "Sofort\nDas Töten eines Gegners erhöht die Bewegungsgeschwindigkeit um 3%. 15-mal stapelbar." }
entries[364881] = { ["name"] = "Materiezerfall", ["text"] = "Unbegrenzte Reichweite\nSofort\nDer aufmerksame Wächter markiert den Spielercharakter für 'Materiezerfall'. Nach 5 Sek. entstehen mehrere Kugeln Antimaterie in einem großen Kreis um den Spielercharakter.\nDie Kugeln bewegen sich auf den Spielercharakter zu und fügen Spielercharakteren, die sie berühren, 83539 kosmischen Schaden zu. Betroffene Spielercharaktere erleiden 10 Sek. lang 100% mehr Schaden durch Antimateriekugeln. Dieser Effekt ist stapelbar.\nWenn 'Materiezerfall' abläuft, wird die Bewegungsgeschwindigkeit des Spielercharakters 10 Sek. lang um 50% verringert." }
