entries[364889] = { ["name"] = "Illusorischer Angriff", ["text"] = "100 Meter Reichweite\nSofort\nInflicts 40 Arcane damage to enemies within 7 yards of the impact." }
entries[364890] = { ["name"] = "Illusorischer Angriff" }
entries[364891] = { ["name"] = "Illusorischer Angriff", ["text"] = "100 Meter Reichweite\nWirken in 1 sek. 1 sek. Abklingzeit\nErschafft Bilder des Zaubernden hinter gegnerischen Zielen in der Nähe, die bei Ablauf kosmischen Schaden verursachen." }
