entries[364893] = { ["name"] = "Gefräßiges Eingraben", ["text"] = "100 Meter Reichweite\nSofort\nSkolex gräbt sich ein und greift an, wenn er feststellt, dass alle Spielercharaktere sich in einer Ballung befinden. Fügt allen Spielercharakteren innerhalb von 10 Metern 46991 körperlichen Schaden zu, stößt sie zurück und verschlingt ihre Anwendungen von ' Ephemerastaub '.\n\nJedes Mal, wenn Skolex sich eingräbt, hinterlässt er ' Kollabierende Leere ' an seiner vorherigen Position und erhält einen Stapel von ' Unersättlich '." }
entries[364897] = { ["name"] = "Animazuflucht" }
entries[364899] = { ["name"] = "Animazuflucht" }
entries[364900] = { ["name"] = "Gestohlenes Wissen", ["text"] = "Wirken in 2 sek. 3 sek. Abklingzeit\nStudiert die Kräfte der Ersten, sodass Angriffe zusätzlichen kosmischen Schaden verursachen." }
entries[364902] = { ["name"] = "Kosmischer Schlag", ["text"] = "8 Meter Reichweite\nSofort\nFügt einem Gegner kosmischen Schaden zu." }
entries[364903] = { ["name"] = "Südwestlicher Poco-Ping" }
entries[364904] = { ["name"] = "Antimaterie", ["text"] = "Unbegrenzte Reichweite\nSofort\nDie Antimateriekugel fügt Spielercharakteren, die sie berühren, 83539 kosmischen Schaden zu.\nAntimaterie erhöht den durch weitere Antimateriekugeln erlittenen Schaden 10 Sek. lang um 100%. Dieser Effekt ist stapelbar." }
entries[364905] = { ["name"] = "Blendendes Licht", ["text"] = "20 Meter Reichweite\nWirken in 1.5 sek. 1 sek. Abklingzeit\nDisorients enemies within 10 yards of the caster for 3 Sek..\nInflicts 25 Arcane damage to enemies within 10 yards." }
entries[364906] = { ["name"] = "Würgen", ["text"] = "Sofort\nSkolex wendet sich einem zufälligen Spielercharakter zu und speit hochgewürgte Säure auf alle Spielercharaktere vor sich, die beim Einschlag 11 Schattenschaden sowie bis Abbruch lang alle 5.2 Sek. 11 Schattenschaden verursacht.\n\nZusätzlich werden Spielercharaktere während der Effektdauer zweimal zufällig teleportiert ." }
entries[364907] = { ["name"] = "Precast Beam" }
entries[364909] = { ["name"] = "Südlicher Poco-Ping" }
entries[364911] = { ["name"] = "Einigkeit", ["text"] = "Runenschnitzmacht\nGewährt einen legendären Effekt Eures auserwählten Pakts.\nRunenschnitzen: Kopf, Hals, Schulter, Brust, Taille, Beine, Füße, Handgelenk, Hände, Finger, Rücken\nQuelle: Ihr benötigt einen respektvollen Ruf bei den Erleuchteten und müsst Runenschnitzen freigeschaltet haben, um diese Erinnerung kaufen zu können.\nBenötigt: Priester" }
entries[364912] = { ["name"] = "Beherrscht", ["text"] = "Sofort\nChance, dass Angriffe zusätzlichen Schattenschaden verursachen.\n(Procchance: 20%, 6s Abklingzeit)" }
entries[364913] = { ["name"] = "Harmonie der Sphären", ["text"] = "Die Abklingzeit von 'Segen der Aufgestiegenen' wird pro Stapel von 'Segen der Aufgestiegenen', der von 'Aufgestiegene Eruption' verbraucht wird, um 3 Sek. verringert, bis zu maximal 60 Sek." }
entries[364914] = { ["name"] = "Schattenwort: Manipulation", ["text"] = "'Gedankenspiele' hält 3 Sek. länger an und kehrt zusätzlich 10% Schaden oder Heilung um. Wenn 'Gedankenspiele' keinen Schaden oder keine Heilung mehr umkehren kann, erhaltet Ihr pro verbleibender Sekunde der Dauer 5% kritischen Trefferwert, der 10 Sek. lang anhält." }
entries[364915] = { ["name"] = "Bwonsamdis Pakt", ["text"] = "Geht einen Pakt mit dem Loa des Todes ein und ruft eine verwunschene Maske hervor, die auf einem Ziel verbleibt, bis 'Faewächter' endet.\n\nVerwunschene Maske: Kopiert den Effekt der aktuell auf dem Ziel aktiven Fee. Folgt Eurem 'Maske leiten'." }
entries[364916] = { ["name"] = "Bleicher Befehl", ["text"] = "Schatten\nDer Einsatz von 'Unheilige Nova' beschwört einen klappernden Magier. Jedes Mal, wenn ein Verbündeter einem mit 'Unheilige Transfusion' belegten Gegner Schaden zufügt, erhöhen sich Schaden und Heilung des klappernden Magiers um 2%, bis zu 100%.\n\nDer klappernde Magier dient Euch 20 Sek. lang und überzieht Euer Ziel mit (25.1% der Zaubermacht) Schattenschaden.\n\nHeilig\nDer Einsatz von 'Unheilige Nova' beschwört einen grüblerischen Kleriker. Jedes Mal, wenn ein Verbündeter einem mit 'Unheilige Transfusion' belegten Gegner Schaden zufügt, erhöhen sich Schaden und Heilung des grüblerischen Klerikers um 2%, bis zu 100%.\n\nDer grüblerische Kleriker dient Euch 20 Sek. lang und heilt einen Verbündeten um (40% der Zaubermacht) Gesundheit.\n\nDisziplin\nDer Einsatz von 'Unheilige Nova' beschwört einen grüblerischen Kleriker. Jedes Mal, wenn ein Verbündeter einem mit 'Unheilige Transfusion' belegten Gegner Schaden zufügt, erhöhen sich Schaden und Heilung des grüblerischen Klerikers um 2%, bis zu 100%.\n\nDer grüblerische Kleriker dient Euch 20 Sek. lang und heilt einen Verbündeten um (40% der Zaubermacht) Gesundheit." }
entries[364917] = { ["name"] = "Malowns Zerschmetterer", ["text"] = "Ca. 1 Procs pro Minute\nSetzt das Ziel 2 Sek. lang außer Gefecht und erhöht die Stärke 30 Sek. lang um 175 ." }
