entries[364933] = { ["name"] = "Sündhafte Woge", ["text"] = "'Verurteilen' erhöht die Effektdauer von [ Waffen : 'Kolossales Schmettern' um 1.5 Sek ] [ Furor : 'Tollkühnheit' um 2.0 Sek /\n\nSchutz\n'Avatar' um 2.5 Sek ]" }
