entries[365112] = { ["name"] = "Tückischer Stern", ["text"] = "300 Meter Reichweite\nSofort\nAnduin entsendet Wellen dunkler Energie, die sich nach außen bewegen und dann an ihren Ursprung zurückkehren. Getroffene Spielercharaktere erleiden alle 1 Sek. 34460 Zwielichtschaden und können nicht angreifen oder Zauber wirken. Hält 4 Sek. lang an.\n\nWenn Anduins Diener von 'Tückischer Stern' getroffen werden, werden sie 10 Sek. lang alle 1 Sek. um 5% ihrer maximalen Gesundheit geheilt und sind währenddessen immun gegen Kontrollverlust- und Unterbrechungseffekte." }
entries[365113] = { ["name"] = "Playtesting" }
entries[365117] = { ["name"] = "Ephemeres Partikel", ["text"] = "Sofort\nJeder verbrauchte Combopunkt verringert die verbleibende Abklingzeit von [ Inkarnation: Avatar von Ashamane : 'Inkarnation: König des Dschungels' / 'Berserker'] um 0.7 Sek." }
