entries[365147] = { ["name"] = "Rune der Herrschaft", ["text"] = "Sofort\nDer Kerkermeister markiert mehrere Spielercharaktere mit einer bösen Rune, die 6 Sek. lang anhält. Bei Ablauf fügt die Rune Spielercharakteren innerhalb von 8 Metern 62654 Schattenschaden zu und löst ' Beherrschender Wille ' an der Position des Spielercharakters aus." }
entries[365150] = { ["name"] = "Rune der Herrschaft", ["text"] = "300 Meter Reichweite\nSofort\nDer Kerkermeister markiert mehrere Spielercharaktere mit einer bösen Rune, die 6 Sek. lang anhält. Bei Ablauf fügt die Rune Spielercharakteren innerhalb von 8 Metern 62654 Schattenschaden zu und löst ' Beherrschender Wille ' an der Position des Spielercharakters aus." }
