entries[365153] = { ["name"] = "Beherrschender Wille", ["text"] = "Unbegrenzte Reichweite\nSofort\nDer Kerkermeister wendet einen Schild an, der die nächsten 2771002 eintreffende Heilung absorbiert. Dieser Effekt wird gleichmäßig auf Ziele innerhalb von 8 Metern um die Zielposition aufgeteilt.\n\nBei Ablauf werden alle Ziele mit ' Herrschaft ' belegt." }
