entries[365159] = { ["name"] = "Pocopocresonanz", ["text"] = "Sofort\nResoniert mit Pocopoc und erhöht die Werte und die Effektivität seiner Gestalten und Fähigkeiten.\n\nDiese Fähigkeit wird mächtiger, je mehr Ihr die Chiffren der Ersten erforscht." }
