entries[365167] = { ["name"] = "Entweihen", ["text"] = "Sofort\nDer Kerkermeister entweiht einen Teil der Kammer für 1 Min., was allen Spielercharakteren im Effektbereich alle 1 Sek. 31327 Schattenschaden zufügt. Jedes Mal, wenn ein Spielercharakter Schaden durch 'Entweihen' erleidet, vergrößert sich der Effektbereich drastisch." }
