entries[365209] = { ["name"] = "Ketten der Pein", ["text"] = "Sofort\nDer Kerkermeister legt sein aktuelles Ziel in Ketten, die ihm 40 Sek. lang alle 2 Sek. 35086 körperlichen Schaden zufügen, wobei der Effekt mit der Zeit stärker wird.\n\nDas Ziel wird mit den nächsten 4 Verbündeten verbunden, die sämtlichen vom Primärziel erlittenen körperlichen Schaden erleiden, bis die Ketten gesprengt werden. Wenn sich Ziele 30 Meter vom Primärziel entfernen, reißt die Kette und 'Kettenbrecher' wird ausgelöst." }
