entries[365549] = { ["name"] = "Robustialisch", ["text"] = "Wirken in 3 sek.\nSchützt den Träger vor Betäubungs-, Bewegungsunfähigkeits- und Verlangsamungseffekten von gegnerischen Kreaturen. Dieser Effekt kann nur einmal alle 30 Sek. auftreten. Dieser Effekt dauert 15 Min. lang an. Funktioniert nur im Freien in den Schattenlanden oder in Oribos." }
